import java.util.Scanner;

public class lilu {
    private static boolean isSeparator(char c) {
        return c == '_' || c == '(' || c == ')';
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = 0;
        int currentSize = 0;
        int wordCount = 0;
        int wordFlag = 0;
        boolean inside = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                wordFlag = 0;
            } else if (c == ')') {
                inside = false;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            }

            if (inside) {
                if (wordFlag != 1 && !isSeparator(c)) {
                    wordCount++;
                    wordFlag = 1;
                }
                if (isSeparator(c)) {
                    wordFlag = 0;
                }
            } else {
                if (!isSeparator(c)) {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

        System.out.println(maxSize + " " + wordCount);
    }
}
